        "text": "For a simple holiday under 30 days, the waiver means you may not need a visa. We still help with the parts that trip people up: **MDAC filing, an itinerary that matches your bookings**, and document checks before you fly. If you are travelling after the scheme ends, staying longer, or going for business that needs a visa, we handle **eNTRI or eVISA** applications as soon as Malaysia confirms the route. Malaysia visa help starts from **₹999** (Travlys fee). We have filed 5,000+ visas with a 98% approval rate. WhatsApp us on **+91 82009 18967**."
