    "slug": "schengen-ees-explained-for-indian-travellers",
    "title": "Schengen EES and ETIAS Explained for Indian Travellers",
    "metaTitle": "Schengen EES and ETIAS for Indian Travellers | Travlys",
    "metaDescription": "EES has been fully live at Schengen borders since 10 April 2026: no passport stamps, a face photo at entry, a digital 90/180 count. ETIAS is not for Indians.",
    "excerpt": "The EU Entry/Exit System has replaced passport stamps at Schengen borders. Here is what it records, what happens at your first entry, how the 90/180 rule is now counted, and why ETIAS does not apply to Indian visa holders.",
