        "text": "India's position moved a lot this year. Reports put it around **80th** in January and **75th** in February. The July 2026 edition, released on 21 July, put India **81st** with 55 destinations after Cape Verde dropped visa on arrival. The **October 2026 edition, dated 9 October**, puts India **84th**, tied with Algeria and Mauritania, with **55 destinations**. These October figures come from Business Today and TravelBiz Monitor. We could not view them on Henley & Partners' own website."
