          "**Mauritius:** visit permit on arrival | about 6 hours from Mumbai | hot summer, cyclone season | hotel booking and return ticket.",
          "**Maldives:** free visa on arrival | about 2.5 to 4 hours | dry season begins | IMUGA declaration."
