        "text": "Until **31 December 2026**, applicants for short-term visas with a stay of up to 180 days do not need to give fingerprints. Applicants for long-stay visas, such as D, J1, Q1, S1, X1 and Z visas, still give fingerprints in person. The notice also lists multiple-entry applicants among those who give fingerprints in principle, so be ready if you apply for one. Children under 14, people over 70, and people fingerprinted by the same mission or centre with the same passport in the last five years are exempt."
